#include <stdio.h>
#include <unistd.h>
#include <sys/types.h>

int main() {
  pid_t pid;
  pid = fork();
  if (pid < 0) {
    fprintf(stderr, "fork failed\n");
    return 1;
  }
  else if (pid == 0) {
    printf("I am the child process (PID: %d)\n", getpid());
  } else {
    printf("I am the parent process (PID: %d, Child PID: %d)\n", getpid(), pid);
  }
  return 0;
}
